// Crohnic: actions the system can run (Siri, Shortcuts, Spotlight, Control Center, Lock Screen,
// Action button). Compiled into both the app and the widget extension, so a control can name the
// intent and the app can run it. Every action opens a screen: the intent leaves the route in the
// shared App Group and the app picks it up as it comes to the foreground.
// Generated by plugins/crohnic-intents.js; edit the copy in plugins/ios.
import AppIntents
import Foundation

enum CrohnicRoute {
  static let group = "group.tr.com.f28.crohnic"
  static let key = "crohnic_pending_route"

  static func request(_ path: String) {
    let defaults = UserDefaults(suiteName: group)
    defaults?.set(path, forKey: key)
    defaults?.set(Date().timeIntervalSince1970, forKey: key + "_at")
  }
}

@available(iOS 17.0, *)
struct CrohnicToiletIntent: AppIntent {
  static let title: LocalizedStringResource = "Tuvalet kaydet"
  static let openAppWhenRun: Bool = true

  func perform() async throws -> some IntentResult {
    CrohnicRoute.request("/tuvalet")
    return .result()
  }
}

